"""Run every statement in a .sql file against a DuckDB database and print each query's result.

Usage:  python run_sql.py shop.duckdb oltp_schema.sql

A comment line such as  -- Q1: revenue by region  just before a query is printed as its title.
"""
import sys

import duckdb


def title_of(query):
    titles = []
    for line in query.strip().splitlines():
        if line.startswith("--"):
            titles.append(line.lstrip("- ").strip())
        elif line.strip():
            break
    return titles[-1] if titles else ""


def show(cur):
    cols = [d[0] for d in cur.description]
    rows = cur.fetchall()
    print(" | ".join(cols))
    for row in rows:
        print(" | ".join("NULL" if v is None else str(v) for v in row))
    print(f"({len(rows)} rows)\n")


def main(db_path, sql_path):
    con = duckdb.connect(db_path)
    with open(sql_path, encoding="utf-8") as f:
        sql = f.read()
    for stmt in con.extract_statements(sql):
        cur = con.execute(stmt.query)
        if stmt.type in (duckdb.StatementType.SELECT, duckdb.StatementType.EXPLAIN):
            if title_of(stmt.query):
                print("==", title_of(stmt.query))
            if stmt.type == duckdb.StatementType.EXPLAIN:
                print(cur.fetchall()[0][1])
            else:
                show(cur)
    con.close()


if __name__ == "__main__":
    if len(sys.argv) != 3:
        sys.exit("usage: python run_sql.py DATABASE_FILE SQL_FILE")
    main(sys.argv[1], sys.argv[2])

-- The co-op's operational (OLTP) database: normalised tables with keys,
-- shaped for recording one sale at a time.
CREATE OR REPLACE TABLE stores (
    store_id   INTEGER PRIMARY KEY,
    store_name VARCHAR NOT NULL,
    town       VARCHAR NOT NULL,
    region     VARCHAR NOT NULL,
    opened     DATE
);
CREATE OR REPLACE TABLE categories (
    category_id   INTEGER PRIMARY KEY,
    category_name VARCHAR NOT NULL,
    department    VARCHAR NOT NULL
);
CREATE OR REPLACE TABLE products (
    product_id   INTEGER PRIMARY KEY,
    sku          VARCHAR NOT NULL UNIQUE,
    product_name VARCHAR NOT NULL,
    category_id  INTEGER NOT NULL REFERENCES categories (category_id),
    list_price   DECIMAL(8, 2) NOT NULL
);
CREATE OR REPLACE TABLE customers (
    customer_id INTEGER PRIMARY KEY,
    first_name  VARCHAR NOT NULL,
    last_name   VARCHAR NOT NULL,
    email       VARCHAR NOT NULL,
    town        VARCHAR NOT NULL,
    segment     VARCHAR NOT NULL,
    joined      DATE NOT NULL
);
CREATE OR REPLACE TABLE orders (
    order_id    INTEGER PRIMARY KEY,
    customer_id INTEGER NOT NULL REFERENCES customers (customer_id),
    store_id    INTEGER NOT NULL REFERENCES stores (store_id),
    order_date  DATE NOT NULL,
    channel     VARCHAR NOT NULL,
    payment     VARCHAR NOT NULL,
    status      VARCHAR NOT NULL
);
CREATE OR REPLACE TABLE order_lines (
    order_id     INTEGER NOT NULL REFERENCES orders (order_id),
    line_no      INTEGER NOT NULL,
    product_id   INTEGER NOT NULL REFERENCES products (product_id),
    quantity     INTEGER NOT NULL,
    unit_price   DECIMAL(8, 2) NOT NULL,
    discount_pct INTEGER NOT NULL,
    PRIMARY KEY (order_id, line_no)
);
INSERT INTO stores SELECT * FROM read_csv('data/stores.csv', header = true);
INSERT INTO categories SELECT * FROM read_csv('data/categories.csv', header = true);
INSERT INTO products SELECT * FROM read_csv('data/products.csv', header = true);
INSERT INTO customers SELECT * FROM read_csv('data/customers.csv', header = true);
INSERT INTO orders SELECT * FROM read_csv('data/orders.csv', header = true);
INSERT INTO order_lines SELECT * FROM read_csv('data/order_lines.csv', header = true);

-- Rows loaded
SELECT 'stores' AS table_name, count(*) AS row_count FROM stores
UNION ALL SELECT 'categories', count(*) FROM categories
UNION ALL SELECT 'products', count(*) FROM products
UNION ALL SELECT 'customers', count(*) FROM customers
UNION ALL SELECT 'orders', count(*) FROM orders
UNION ALL SELECT 'order_lines', count(*) FROM order_lines;

