SELECT c.town, sum(f.net_amount) AS net
FROM fact_sales AS f JOIN dim_customer AS c USING (customer_key)
WHERE c.customer_id = 3 GROUP BY c.town;

CREATE MATERIALIZED VIEW agg_sales_month AS
SELECT d.year_month, f.store_key, p.category, p.department,
       count(*) AS order_lines, sum(f.net_amount) AS net_amount
FROM fact_sales AS f
JOIN dim_date AS d USING (date_key)
JOIN dim_product AS p USING (product_key)
GROUP BY d.year_month, f.store_key, p.category, p.department;

CREATE UNIQUE INDEX ON agg_sales_month (year_month, store_key, category);
REFRESH MATERIALIZED VIEW CONCURRENTLY agg_sales_month;
